import{z as i,x as s,o as r,c,q as t,j as n,D as E,d as B,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"外汇的宏观策略","description":"","frontmatter":{"title":"外汇的宏观策略","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mac-fx-macro.md","filePath":"quant/mac-fx-macro.md","lastUpdated":1791063341000}'),d={name:"quant/mac-fx-macro.md"};function p(m,a,D,f,u,P){const A=s("Mermaid");return r(),c("div",null,[a[2]||(a[2]=t('<h1 id="外汇的宏观策略" tabindex="-1">外汇的宏观策略 <a class="header-anchor" href="#外汇的宏观策略" aria-label="Permalink to &quot;外汇的宏观策略&quot;">​</a></h1><div class="epigraph"><p>外汇没有现金流可分析：每一笔头寸都是一次相对宏观投票，你买的从来不是一张货币，而是两个经济体、两家央行之间的差。</p><footer>—— 据 Lustig, Roussanov &amp; Verdelhan, Journal of Finance, 2011 与 Menkhoff, Sarno, Schmeling &amp; Schrimpf, JFE, 2012 整理</footer></div><p><a href="/quant/mac-rates-strategies">上一课</a>把宏观观点拆到利率三轴上。但「两个经济体之差」还有更直接的账户：汇率。利率给出差的斜率，汇率给出差的价格；本课讲外汇如何消费前三课的状态概率、象限与利率输出，以及它自带的 carry、价值与美元周期。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>外汇信号的三个来源各有陷阱。carry 用利差或远期升水排序（<a href="/quant/fx-carry-mom">外汇 carry 与动量</a>），但远期升水被利率差套住——CIP 保证买入远期不等于看多，赚的是 UIP 失败的溢价，即市场为崩溃风险卖的保险，左尾是保价不是意外。价值用实际汇率对中枢的偏离（<a href="/quant/ppp-anchor">PPP 锚</a>），但中枢本身以年计漂移。美元不是第三个信号而是全局因子：美元走强通常对应全球 funding 收紧——第三课第三条链在外汇上的定价，EM 与 DM 在这条链上不对称。缺口是把利差观点与汇率观点分开记账，把美元周期当状态而不是当一篮子货币的均值；混起来，崩月会被误诊成判断错，而不是保险被行权。</p><p><span class="marginnote">「carry」翻译成白话：借低利率货币、存高利率货币，赚中间的利差。CIP 是「远期价格必须把利差算进去」的套利约束；UIP 则断言「利差会被贬值精确抵消」。carry 能赚钱，靠的正是 UIP 长期不成立。</span></p><h3 id="从象限到利差到汇率" tabindex="-1">从象限到利差到汇率 <a class="header-anchor" href="#从象限到利差到汇率" aria-label="Permalink to &quot;从象限到利差到汇率&quot;">​</a></h3><p>宏观链条逐环落：增长与通胀象限决定两家央行的反应函数差，反应函数差投影成政策利率路径差，路径差的现值就是远期曲线——carry 是这条链的静止像，象限换格时静止像跟着重画。表达上三因子合并：carry 给排序、价值给慢偏置、动量给方向确认，按波动缩放后合成。避险态美元走强的 smile 让美元空头天然承担状态尾部——第一课的资产内生代理里，美元本身就是状态变量之一。</p><p><span class="marginnote">Rogoff 汇总的证据：实际汇率的半衰期约三到五年。PPP 信号的有效调仓频率因此是年级——把它当周度信号，等于用漂移中的中枢放大噪声。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地分三层。信号层：carry 按远期升水排序并按波动缩放；价值用实际汇率对多年中枢的偏离，只做偏置不做触发；动量与 carry 相关有限，分开构造。组合层：美元因子单独记账——所有外币对美元的平均不是套息，是全局风险暴露；EM 腿按单一货币设容量与干预限额，与 DM 腿分账。执行层：管制货币走 NDF，远期点与即期的脱钩要按<a href="/quant/fx-market-structure">外汇市场结构</a>的分层报价处理；对冲比率是显式决策——把外币债券对冲回本币，同时把它的 carry 一并对冲掉，这笔成本按基差入账，不进收益。</p>',11)),(r(),n(l,null,{default:E(()=>[o(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GA%5B%22A%20%E5%9B%BD%E5%A2%9E%E9%95%BF-%E9%80%9A%E8%83%80%22%5D%20--%3E%20RA%5B%22%E5%A4%AE%E8%A1%8C%E5%8F%8D%E5%BA%94%E5%87%BD%E6%95%B0%22%5D%0A%20%20GB%5B%22B%20%E5%9B%BD%E5%A2%9E%E9%95%BF-%E9%80%9A%E8%83%80%22%5D%20--%3E%20RB%5B%22%E5%A4%AE%E8%A1%8C%E5%8F%8D%E5%BA%94%E5%87%BD%E6%95%B0%22%5D%0A%20%20RA%20--%3E%20RD%5B%22%E5%88%A9%E7%8E%87%E8%B7%AF%E5%BE%84%E5%B7%AE%22%5D%0A%20%20RB%20--%3E%20RD%0A%20%20RD%20--%3E%20CA%5B%22carry%EF%BC%9A%E8%BF%9C%E6%9C%9F%E5%8D%87%E6%B0%B4%22%5D%0A%20%20PP%5B%22PPP%20%E4%BB%B7%E5%80%BC%E5%81%8F%E7%BD%AE%22%5D%20--%3E%20CO%5B%22%E4%B8%89%E5%9B%A0%E5%AD%90%E5%90%88%E6%88%90%22%5D%0A%20%20CA%20--%3E%20CO%0A%20%20MO%5B%22%E5%8A%A8%E9%87%8F%22%5D%20--%3E%20CO%0A%20%20CO%20--%3E%20US%5B%22%E7%BE%8E%E5%85%83%E5%9B%A0%E5%AD%90%E5%8D%95%E7%8B%AC%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20CO%20--%3E%20EX%5B%22%E5%B7%A5%E5%85%B7%EF%BC%9A%E5%8D%B3%E6%9C%9F%2F%E8%BF%9C%E6%9C%9F%2FNDF%22%5D%0A%20%20US%20--%3E%20EX%0A%20%20EX%20--%3E%20CR%5B%22%E5%B4%A9%E6%BA%83%E4%B8%8E%E5%88%B6%E5%BA%A6%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"carry 为什么有溢价：CIP 套汇把远期升水钉在利率差上，若 UIP 成立，利差应被即期贬值精确抵消，carry 交易零收益；实证的失败意味着高息货币的贬值慢于利差——溢价是对崩溃月的补偿，机制是灾害风险与杠杆化套息的被迫平仓，第三课的保证金螺旋正是平仓的执行通道。美元的机制是同一条链的另一头：美元融资的杠杆在 global funding 收紧时被迫还美元、买美元，美元升值与跨资产相关性塌向 1 同时出现。所以美元因子与衰退格、流动性紧缩态天然同向：做套息等于系统性做空状态尾部，崩月亏损可以吃掉整年的 carry 收入。",-1)),(r(),n(l,null,{default:E(()=>[o(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CIP%5B%22CIP%3A%20%E8%BF%9C%E6%9C%9F%E5%8D%87%E6%B0%B4%E9%92%89%E4%BD%8F%E5%88%A9%E5%B7%AE%22%5D%20--%3E%20UIP%5B%22%E8%8B%A5%20UIP%20%E6%88%90%E7%AB%8B%3A%20%E5%88%A9%E5%B7%AE%E8%A2%AB%E8%B4%AC%E5%80%BC%E6%8A%B5%E6%B6%88%22%5D%0A%20%20UIP%20--%3E%20Z%5B%22carry%20%E5%BA%94%E9%9B%B6%E6%94%B6%E7%9B%8A%22%5D%0A%20%20Z%20--%3E%20F%5B%22%E5%AE%9E%E8%AF%81%3A%20%E9%AB%98%E6%81%AF%E8%B4%A7%E5%B8%81%E8%B4%AC%E5%80%BC%E6%85%A2%E4%BA%8E%E5%88%A9%E5%B7%AE%22%5D%0A%20%20F%20--%3E%20P%5B%22%E6%BA%A2%E4%BB%B7%20%3D%20%E5%B4%A9%E6%BA%83%E9%A3%8E%E9%99%A9%E7%9A%84%E4%BF%9D%E9%99%A9%E8%B4%B9%22%5D%0A%20%20P%20--%3E%20Calm%5B%22%E5%B9%B3%E9%9D%99%E6%9C%88%3A%20%E7%A8%B3%E5%AE%9A%E6%94%B6%E4%BF%9D%E8%B4%B9%22%5D%0A%20%20Calm%20--%3E%20CR%5B%22%E5%B4%A9%E6%9C%88%3A%20%E6%9D%A0%E6%9D%86%E5%A5%97%E6%81%AF%E8%A2%AB%E8%BF%AB%E5%B9%B3%E4%BB%93%22%5D%0A%20%20CR%20--%3E%20L%5B%22%E4%B8%80%E6%AC%A1%E5%B4%A9%E6%BA%83%E5%8F%AF%E5%90%83%E6%8E%89%E5%85%A8%E5%B9%B4%E6%94%B6%E7%9B%8A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">carry 交易可以想象成卖地震险：绝大多数月份稳稳收保费（利差），偶尔一次大地震（危机中的货币崩盘）把多年保费一次赔光。所以评估 carry 不能只看平均收益，要看最差的几个月发生时还剩多少。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>UIP 失败不是免费午餐：单个货币对的排序收益极不稳，收益靠几十个货币对的分散吃，且崩溃月 carry 与趋势同亏（carry 课的口径），去重后仍要单独报极端月。2008 年后交叉货币基差改写了 carry 的含义：对冲成本不等于利差，按旧口径算的套息在基差里漏钱。PPP 的中枢随贸易条件与生产率移动，把全样本均值当永恒公允会系统性偏。干预与资本管制让远期与即期分层，NDF 贴水不是可执行价格。也不把美元负相关写成机制：美元与商品同受全球 funding 与风险偏好驱动，相关性是共同因子的投影，不是因果——这是下一课的入口。</p><p><span class="marginnote">常见误区：以为「对冲了汇率风险就万事大吉」。把一笔外币债券对冲回本币，它的 carry 也被一并对冲掉；2008 年后对冲本身还要付交叉货币基差成本。对冲是一笔有价格的显式交易，不是免费保险。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>远期升水是利率差的静止像；carry 赚 UIP 失败的溢价，左尾是保价不是意外。</li><li>三因子分工：carry 排序、PPP 慢偏置、动量确认；美元因子单独记账。</li><li>美元走强与 funding 收紧同源，套息等于系统性做空状态尾部。</li><li>对冲比率是显式决策：对冲即把 carry 一并对冲掉，基差成本入账。</li><li>出处：Lustig, Roussanov &amp; Verdelhan, Journal of Finance, 2011；Menkhoff 等, JFE, 2012；Rogoff, Journal of Economic Literature, 1996；排序与执行见<a href="/quant/fx-carry-mom">外汇 carry 与动量</a>、<a href="/quant/ppp-anchor">PPP 锚</a>与<a href="/quant/fx-market-structure">外汇市场结构</a>。</li></ul>',6))])}const F=i(d,[["render",p]]);export{C as __pageData,F as default};
